use crate::{Error, Result};

/// IDs are generated by the client as UUIDv7. We only accept the canonical
/// lowercase hyphenated form so the same entity can't appear under two spellings.
pub fn check(id: &str) -> Result<()> {
    let parsed = uuid::Uuid::parse_str(id).map_err(|_| Error::invalid(format!("invalid id: {id}")))?;
    if parsed.get_version_num() != 7 {
        return Err(Error::invalid(format!("id must be a UUIDv7: {id}")));
    }
    if parsed.hyphenated().to_string() != id {
        return Err(Error::invalid(format!("id must be lowercase hyphenated: {id}")));
    }
    Ok(())
}

/// Trims and validates a user-visible name (folder name or note title).
pub fn clean_name(name: &str) -> Result<String> {
    let name = name.trim();
    if name.is_empty() {
        return Err(Error::invalid("name cannot be empty"));
    }
    if name.chars().count() > 200 {
        return Err(Error::invalid("name is too long (max 200 characters)"));
    }
    if name.contains(['\n', '\r']) {
        return Err(Error::invalid("name cannot contain line breaks"));
    }
    Ok(name.to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn accepts_v7() {
        check(&crate::test_util::id()).unwrap();
    }

    #[test]
    fn rejects_other_versions_and_forms() {
        assert!(check("not-a-uuid").is_err());
        assert!(check("67e55044-10b1-426f-9247-bb680e5fe0c8").is_err()); // v4
        let upper = crate::test_util::id().to_uppercase();
        assert!(check(&upper).is_err());
    }

    #[test]
    fn cleans_names() {
        assert_eq!(clean_name("  Hello ").unwrap(), "Hello");
        assert!(clean_name("   ").is_err());
        assert!(clean_name("a\nb").is_err());
        assert!(clean_name(&"x".repeat(201)).is_err());
    }
}
